// ---- Hạ tầng đa ngôn ngữ (2026-08) ----
// Giữ NGUYÊN "nameVi"/"description" như cũ (không đổi field, không đổi
// hành vi hiện có ở BẤT KỲ nơi nào đang dùng trực tiếp 2 field này) —
// thêm MỚI "nameTranslations"/"descriptionTranslations" chứa các ngôn
// ngữ KHÁC (đầu tiên: "en", verify đúng thuật ngữ chính thức bản 7.0 +
// dịch tay mô tả cơ chế, vì đây là nội dung giải thích gốc của site,
// không phải text lấy thẳng từ game nên không có nguồn tự động như
// genshin-db). Các ngôn ngữ còn lại (ja, ko, zh-CN...) sẽ bổ sung dần ở
// đợt sau — cấu trúc dưới đây đã sẵn sàng nhận thêm mà không cần đổi gì.
export type OtherLocale = "en" | "zh-CN" | "zh-TW" | "ja" | "ko" | "id" | "th" | "de" | "fr" | "it" | "pt" | "es" | "ru" | "tr";

function pickTranslation(
  translations: Partial<Record<OtherLocale, string>> | undefined,
  locale: string,
  viFallback: string
): string {
  if (locale === "vi") return viFallback;
  return translations?.[locale as OtherLocale] ?? translations?.en ?? viFallback;
}

export interface ElementalReaction {
  id: string;
  name: string;
  nameVi: string;
  elements: string[];
  category: ReactionCategory;
  description: string;
  requiresCharacters?: string;
  // Nguyên tố dùng để tô màu chữ tên phản ứng + pill (elements/page.tsx,
  // reactionAccentColor bên dưới) — nguyên tố "đặc trưng"/thị giác thật
  // sự của phản ứng đó, KHÔNG PHẢI cứ lấy phần tử đầu của elements[].
  // Quy ước chọn (đối chiếu icon/hiệu ứng thật trong game):
  //   - Khuếch Tán (Swirl) / Kết Tinh (Crystallize): luôn là nguyên tố
  //     KÍCH HOẠT cố định (Anemo / Geo) — nguyên tố bị cuốn theo thay đổi
  //     tuỳ trận nên không dùng làm màu đại diện được.
  //   - Đóng Băng: Cryo (hiệu ứng đóng băng rõ ràng nhất là băng giá).
  //   - Sinh Trưởng/Tăng Cường/Lan Tràn (Quicken/Aggravate/Spread): Dendro
  //     — cả 3 đều hiện dấu hiệu vàng-xanh lá đặc trưng của Dendro trong
  //     game, dù có Lôi tham gia.
  //   - Nở Rộ (Hyperbloom): Electro — chính Lôi là thứ biến hạt giống
  //     thành đạn truy đuổi. Bung Tỏa (Burgeon): Pyro — chính Hỏa là thứ
  //     làm hạt giống nổ mạnh hơn.
  //   - Phản ứng Khuếch Đại (Bốc Hơi/Tan Chảy) CỐ TÌNH không đặt
  //     accentElement — giữ tông đỏ cam "nhân sát thương" chung, đúng quy
  //     ước cộng đồng/wiki thay vì tô theo 1 trong 2 nguyên tố tham gia.
  accentElement?: string;
  // Tên tiếng Anh ("Vaporize"...) đã có sẵn ở field `name` — không cần
  // lặp lại trong đây. Chỉ chứa các ngôn ngữ NGOÀI vi/en.
  nameTranslations?: Partial<Record<Exclude<OtherLocale, never>, string>>;
  descriptionTranslations?: Partial<Record<OtherLocale, string>>;
}

